use verus::prelude::*;

verus! {
    /// Given a non‐empty vector `list` of i32 and a 1‐based position `k` with
    /// 1 ≤ k < list.len(), returns a new vector with the element at position k
    /// removed.  The order of the remaining elements is preserved.
    pub fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
        // Preconditions
        requires(list.len() >= 1);
        requires(k >= 1 && k < list.len());
        // Let idx be the 0‐based index we remove
        let idx = k - 1;

        // Postconditions
        ensures(|new_list: &Vec<i32>| {
            // Length is one less than the original
            new_list.len() == list.len() - 1
            // For each position j in the result, we get list[j] if j < idx,
            // otherwise we get list[j+1].
            && forall(|j: usize| 
                j < new_list.len() ==>
                if j < idx { new_list[j] == list[j] }
                else      { new_list[j] == list[j + 1] }
            )
        });

        // We'll build the result by iterating and skipping idx
        let mut res: Vec<i32> = Vec::new();
        let mut i: usize = 0;

        while i < list.len() {
            // Loop invariants
            invariant(i <= list.len());
            // The length of res is i until we pass idx, then it's i-1
            invariant(res.len() == if i <= idx { i } else { i - 1 });
            // At every point, the partial result matches the desired slicing
            invariant(forall(|j: usize|
                j < res.len() ==>
                if j < idx { res[j] == list[j] }
                else      { res[j] == list[j + 1] }
            ));
            decreases(list.len() - i);

            if i != idx {
                res.push(list[i]);
            }
            i += 1;
        }

        res
    }
}